<?php $titles=array('BASTB'=>'BASTB / Berita Acara Serah Terima BBM','RDT'=>'BA / RDT — Sounding Pengisian BBM','PASS'=>'Pass Pelabuhan');$get=function($k)use($form){return isset($form[$k])?$form[$k]:'';}; ?>
