<?php if(!$row): ?><div class="box box-primary"><div class="box-header"><h3 class="box-title">Pilih sumber untuk Auto Fill</h3></div><div class="box-body"><form method="get" class="row">
<?php if($kind==='BASTB'): ?><div class="col-sm-4 form-group"><label>SPP</label><select name="CaptureID" class="form-control" required><option value="">Pilih SPP yang sudah dikonfirmasi</option><?php foreach($captures as $c): ?><option value="<?= (int)$c['CaptureID'] ?>" <?= (int)($links['CaptureID']??0)===(int)$c['CaptureID']?'selected':'' ?>><?= html_escape('#'.$c['CaptureID'].' — '.$c['LONumber'].' — '.$c['Buyer'].' / '.$c['Status']) ?></option><?php endforeach; ?></select></div><div class="col-sm-4 form-group"><label>Kapal penerima</label><select name="VesselID" class="form-control" required><option value="">Pilih kapal</option><?php foreach($vessels as $v): ?><option value="<?= (int)$v['VesselID'] ?>" <?= (int)($links['VesselID']??0)===(int)$v['VesselID']?'selected':'' ?>><?= html_escape($v['VesselName'].' — '.$v['CompanyName'].' / Area '.$v['SpbbID']) ?></option><?php endforeach; ?></select></div><div class="col-sm-4 form-group"><label>Permohonan Bunker (opsional)</label><select name="BunkerID" class="form-control"><option value="">Tanpa permohonan</option><?php foreach($bunkers as $b): ?><option value="<?= (int)$b['BunkerID'] ?>" <?= (int)($links['BunkerID']??0)===(int)$b['BunkerID']?'selected':'' ?>><?= html_escape($b['RequestNo']) ?></option><?php endforeach; ?></select></div>
<?php else: ?><div class="col-sm-9 form-group"><label>BASTB sumber</label><select name="ParentID" class="form-control" required><option value="">Pilih BASTB</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['OperationID'] ?>" <?= (int)($links['ParentID']??0)===(int)$p['OperationID']?'selected':'' ?>><?= html_escape($p['DocumentNo'].' — '.$p['CompanyName'].' — '.$p['VolumeLiters'].' liter') ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-sm-12"><button class="btn btn-primary">Ambil Data / Auto Fill</button></div></form></div></div><?php endif; ?>
<?php if(isset($links['VesselID'])): ?><div class="box box-success"><div class="box-body"><p class="text-muted">Sumber tersimpan sebagai snapshot. Lengkapi data yang tidak ada pada SPP/permohonan. Hasil sounding adalah hasil ukur aktual, bukan kapasitas tangki.</p><?php if($kind==='BASTB'&&!empty($form['DepotExitTime'])): ?><p>Jam keluar depot pada SPP: <b><?= html_escape($form['DepotExitTime']) ?></b>. Isi jam pengisian aktual di bawah.</p><?php endif; ?><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><?php foreach(array('CaptureID','VesselID','BunkerID','ParentID') as $key): ?><input type="hidden" name="<?= $key ?>" value="<?= (int)($links[$key]??0) ?>"><?php endforeach; ?><input type="hidden" name="Version" value="<?= (int)($row['Version']??0) ?>"><div class="row">
<?php foreach($fields as $key=>$meta): ?><div class="col-sm-6 form-group"><label><?= html_escape($meta[0]) ?></label><?php if($key==='VehicleType'): ?><select class="form-control" name="VehicleType" required><option value="">Pilih jenis kendaraan sesuai tarif</option><?php $seen=array();foreach($tariffs as $t):if((int)$t['SpbbID']!==(int)$links['SpbbID']||isset($seen[$t['VehicleType']]))continue;$seen[$t['VehicleType']]=true; ?><option value="<?= html_escape($t['VehicleType']) ?>" <?= $get('VehicleType')===$t['VehicleType']?'selected':'' ?>><?= html_escape($t['VehicleType']) ?></option><?php endforeach; ?></select><?php else: ?><input class="form-control" name="<?= $key ?>" type="<?= $meta[1] ?>" value="<?= html_escape($get($key)) ?>" maxlength="<?= $meta[2] ?>" <?= $key==='DocumentNo'?'placeholder="Otomatis saat disimpan jika dikosongkan"':'required' ?> <?= in_array($key,array('VesselName','CompanyName'),true)?'readonly':'' ?> <?= $meta[1]==='number'?'min="0" max="1000000000" step="0.001"':'' ?>><?php endif; ?></div><?php endforeach; ?>
<?php if($kind==='BASTB'): ?><div class="col-sm-6 form-group"><label>Perusahaan Penagihan (supplier / pengguna fasilitas)</label><input name="BillingCompany" class="form-control" value="<?= html_escape($get('BillingCompany')) ?>" maxlength="200" required><small>Digunakan untuk mengelompokkan invoice; dapat berbeda dari perusahaan pemilik kapal.</small></div><?php endif; ?></div><button class="btn btn-success">Simpan &amp; Preview</button> <a class="btn btn-default" href="<?= site_url('Pipeline_documents/index/'.$kind) ?>">Daftar Dokumen</a></form></div></div><?php endif; ?></section></div>

<?php if(isset($links['VesselID'])&&in_array($kind,array('RDT','PASS'),true)): ?>
<script>(function(){var form=document.querySelector('form[method="post"]');if(!form)return;var box=document.createElement('div');box.className='alert alert-info';box.style.marginTop='16px';form.appendChild(box);var kind=<?= json_encode($kind) ?>,tariffs=<?= json_encode(array_values(array_filter($tariffs,function($t)use($links){return (int)$t['SpbbID']===(int)$links['SpbbID'];})),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
function number(name){return Number(form.elements[name]&&form.elements[name].value)||0;}function update(){if(kind==='RDT'){var before=0,after=0;['Main1','Main2','DailyRight','DailyLeft'].forEach(function(t){before+=number('Before'+t);after+=number('After'+t);});box.textContent='Total sebelum: '+before.toLocaleString('id-ID')+' L · Total sesudah: '+after.toLocaleString('id-ID')+' L · Selisih: '+(after-before).toLocaleString('id-ID')+' L · Pengisian BASTB: '+number('VolumeLiters').toLocaleString('id-ID')+' L';}else{var type=form.elements.VehicleType.value,date=form.elements.DocumentDate.value,t=tariffs.find(function(t){return t.VehicleType===type&&t.EffectiveDate.slice(0,10)<=date;});box.textContent=t?'Perkiraan total Pass: '+new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(number('PeopleCount')*Number(t.PersonRate)+number('VehicleCount')*(Number(t.VehicleRate)+Number(t.BerthRate))):'Tarif belum tersedia untuk jenis kendaraan / tanggal terpilih.';}}form.addEventListener('input',update);form.addEventListener('change',update);update();})();</script>
<?php endif; ?>
